sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') {
        return;
    }

    switch (newValue) {
        case 'excellent':
            alert("Thank you for your excellent feedback!");
            break;
        case 'good':
            alert("Thanks! We appreciate your good rating.");
            break;
        case 'average':
            alert("Thanks for your feedback — we'll keep improving!");
            break;
        case 'poor':
            alert("Sorry to hear that. We’ll work to improve.");
            break;
        default:
            alert("Thank you for your feedback!");
    }
}
